function longestConsecutive(nums) {
  const set = new Set(nums);
  let best = 0;

  for (const num of set) {
    if (set.has(num - 1)) continue;   // not a start, skip

    let length = 1;
    while (set.has(num + length)) length++;

    best = Math.max(best, length);
  }
  return best;
}
